css:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.print-format {
  margin: 5px !important;
  padding: 5px !important;
  width: 100% !important;
}

html, body {
  margin: 0 !important;
  padding: 0 !important;
  font-family: 'Helvetica', 'Arial', sans-serif;
  background-color: white;
  line-height: 1.4;
  font-size: 12px;
  color: #000;
}

.sid-invoice {
  background-color: white;
  width: 100%;
}

.sid-header {
  text-align: center;
  margin-bottom: 10px;
}

.sid-logo {
  max-width: 70px;
  max-height: 70px;
  height: auto;
  margin-bottom: 4px;
}

.sid-school-name {
  font-size: 20px;
  font-weight: bold;
  color: #4b1a6b;
}

.sid-tagline {
  font-size: 11px;
  font-style: italic;
  color: #555;
  margin-bottom: 4px;
}

.sid-contact-line {
  font-size: 11px;
  text-decoration: underline;
  margin-bottom: 12px;
}

.sid-title-row {
  text-align: right;
  margin-bottom: 6px;
}

.sid-doc-title {
  font-size: 15px;
  font-weight: bold;
}

.sid-info-box {
  float: right;
  margin-bottom: 10px;
}

.sid-info-table {
  border-collapse: collapse;
}

.sid-info-table td {
  padding: 1px 4px;
  font-size: 12px;
  border: none !important;
  white-space: nowrap;
}

.sid-info-label {
  text-align: left;
}

.sid-info-value {
  text-align: right;
  font-weight: bold;
}

.sid-fees-table {
  clear: both;
  width: 100%;
  border-collapse: collapse;
  margin-top: 20px;
}

.sid-fees-header {
  text-align: left;
  font-style: italic;
  font-weight: bold;
  border-bottom: 1px solid #000 !important;
  padding: 4px 2px;
}

.sid-fees-table td {
  padding: 4px 2px;
  border-bottom: 1px solid #ddd !important;
  font-size: 12px;
}

.sid-text-right {
  text-align: right !important;
}

.sid-total-row {
  text-align: right;
  font-weight: bold;
  margin-top: 10px;
  padding-top: 6px;
  border-top: 1px solid #000;
}

.sid-total-label,
.sid-total-value {
  display: inline-block;
  margin-right: 16px;
}

.sid-footer {
  width: 100%;
  border-collapse: collapse;
  margin-top: 30px;
  padding-top: 10px;
  border-top: 1px solid #ddd;
}

.sid-payment-details,
.sid-notes {
  width: 50%;
  vertical-align: top;
  font-size: 11px;
  padding-right: 20px;
}

.sid-payment-details div,
.sid-notes div {
  margin-bottom: 3px;
}

.sid-footer-title {
  font-weight: bold;
  margin-bottom: 6px !important;
}

.sid-footer-label {
  font-weight: bold;
}

.sid-notes-text {
  white-space: pre-wrap;
}

.sid-remittance {
  margin-top: 24px;
  padding-top: 10px;
  border-top: 1px dashed #999;
}

.sid-remittance-title {
  font-weight: bold;
  margin-bottom: 8px;
}

.sid-remittance-body {
  width: 100%;
  border-collapse: collapse;
}

.sid-remittance-left {
  vertical-align: top;
}

.sid-remittance-right {
  vertical-align: top;
  text-align: right;
}

.sid-remittance-left div {
  font-size: 11px;
  margin-bottom: 3px;
}

.sid-due-note {
  margin-top: 8px !important;
}

.sid-total-due-box {
  border-collapse: collapse;
}

.sid-total-due-box td {
  border: 1px solid #000 !important;
  padding: 6px 10px;
  font-weight: bold;
  font-size: 12px;
}
